    /**
     * Method to retrieve the Adjuster via AdjusterFetchOneSummary
     * @param 	summary AdjusterFetchOneSummary 
     * @return 	AdjusterFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Adjuster getAdjuster( AdjusterFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "AdjusterFetchOneSummary arg cannot be null" );
    	
    	Adjuster entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Adjuster
        	// --------------------------------------
        	CompletableFuture<Adjuster> futureEntity = queryGateway.query(new FindAdjusterQuery( new LoadAdjusterFilter( summary.getAdjusterId() ) ), ResponseTypes.instanceOf(Adjuster.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Adjuster with id " + summary.getAdjusterId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


