    /**
     * add Claim to Claims 
     * @param		command AssignClaimsToAdjusterCommand
     * @exception	ProcessingException
     */     
	public void addToClaims( AssignClaimsToAdjusterCommand command ) throws ProcessingException {
		
		
		// -------------------------------------------
		// load the parent
		// -------------------------------------------
		load( command.getAdjusterId() );

		ClaimService childDelegate 	= ClaimService.getClaimInstance();
		AdjusterService parentDelegate = AdjusterService.getAdjusterInstance();		
		UUID childId = command.getAddTo().getClaimId();
		
		try {		
			// --------------------------------------
	    	// validate the command
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );			
		}
		catch( Exception exc ) {
			final String msg = "Failed to add a Claim as Claims to Adjuster" ; 
			LOGGER.log( Level.WARNING, msg, exc );
			throw new ProcessingException( msg, exc );
		}

	}

